<script setup>
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import Icon from '../../../Components/Icon.vue';

const props = defineProps({ sale: Object, items: Array, returns: Array, returnItems: Array, movements: Array });
const page = usePage();
const permissions = computed(() => page.props.auth.permissions || []);
const canRefund = computed(() => permissions.value.includes('refund_sale'));
const canVoid = computed(() => permissions.value.includes('void_sale'));
const money = (value) => new Intl.NumberFormat('en-TZ', { style: 'currency', currency: page.props.store.currency, maximumFractionDigits: 0 }).format(Number(value || 0));
const today = new Date().toISOString().slice(0, 10);
const returnForm = useForm({ return_date: today, reason: '', refund_method: 'cash', notes: '', items: props.items.map((item) => ({ sale_item_id: item.id, quantity: 0, restock: true })) });
const voidForm = useForm({ reason: '' });
const selectedRefund = computed(() => returnForm.items.reduce((sum, row, index) => sum + Number(row.quantity || 0) * Number(props.items[index]?.unit_price || 0), 0));
const submitReturn = () => returnForm.post(`/admin/sales/pos/${props.sale.id}/returns`, { preserveScroll: true });
const submitVoid = () => { if (confirm('Void this completed POS sale and restore all sold stock?')) voidForm.post(`/admin/sales/pos/${props.sale.id}/void`, { preserveScroll: true }); };
</script>

<template>
<AdminLayout>
    <Head :title="`POS Sale ${sale.reference}`" />
    <div class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><Link href="/admin/sales" class="mb-3 inline-flex items-center gap-1 text-sm font-semibold text-prinx-600"><Icon name="arrow-left-2" :size="15" /> Sales</Link><p class="section-kicker">POS transaction</p><h1 class="section-title">{{ sale.reference }}</h1><p class="mt-2 text-sm text-slate-500">{{ sale.customer_name || 'Walk-in customer' }} · {{ new Date(sale.created_at).toLocaleString() }}</p></div><div class="flex gap-2"><Link :href="`/admin/pos/receipt/${sale.id}`" class="btn-light"><Icon name="printer" :size="16" /> Receipt</Link><span :class="['rounded-[8px] px-3 py-2 text-xs font-semibold', sale.status === 'voided' ? 'bg-red-50 text-red-700' : sale.status === 'completed' ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700']">{{ sale.status }}</span></div></div>

    <div class="mt-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><div class="metric-card"><p class="text-xs text-slate-500">Sale total</p><b class="mt-2 block text-xl">{{ money(sale.total) }}</b></div><div class="metric-card"><p class="text-xs text-slate-500">Refunded</p><b class="mt-2 block text-xl">{{ money(sale.refunded_amount) }}</b></div><div class="metric-card"><p class="text-xs text-slate-500">Payment</p><b class="mt-2 block text-base capitalize">{{ sale.payment_method }}</b></div><div class="metric-card"><p class="text-xs text-slate-500">Amount paid</p><b class="mt-2 block text-xl">{{ money(sale.amount_paid) }}</b></div><div class="metric-card"><p class="text-xs text-slate-500">Cashier</p><b class="mt-2 block text-base">{{ sale.cashier_name || '—' }}</b></div></div>

    <div class="mt-6 grid gap-6 xl:grid-cols-[1.1fr_.9fr]">
        <div class="space-y-6">
            <div class="card overflow-x-auto"><div class="border-b border-slate-200 px-5 py-4"><h2 class="font-semibold">Sold items</h2></div><table class="admin-table"><thead><tr><th>Product</th><th>Sold</th><th>Returned</th><th>Unit price</th><th>Total</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><p class="font-semibold">{{ item.product_name }}</p><p class="text-xs text-slate-500">{{ item.sku || '—' }}</p></td><td>{{ item.quantity }}</td><td>{{ item.quantity_returned }}</td><td>{{ money(item.unit_price) }}</td><td class="font-semibold">{{ money(item.line_total) }}</td></tr></tbody></table></div>

            <form v-if="canRefund && sale.status !== 'voided' && sale.status !== 'returned'" class="card p-5" @submit.prevent="submitReturn"><div class="flex items-start justify-between"><div><h2 class="font-semibold">Return / refund</h2><p class="mt-1 text-xs text-slate-500">Choose quantities and whether each returned item is fit to go back into sellable stock.</p></div><Icon name="refresh-circle" :size="22" /></div><div v-if="returnForm.errors.return" class="mt-4 rounded-[8px] bg-red-50 px-3 py-2 text-sm text-red-700">{{ returnForm.errors.return }}</div><div class="mt-4 space-y-3"><div v-for="(row,index) in returnForm.items" :key="row.sale_item_id" class="grid gap-3 rounded-[9px] border border-slate-200 p-3 sm:grid-cols-[1fr_100px_130px]"><div><p class="font-semibold">{{ items[index].product_name }}</p><p class="text-xs text-slate-500">Available to return: {{ items[index].quantity - items[index].quantity_returned }}</p></div><input v-model.number="row.quantity" type="number" min="0" :max="items[index].quantity - items[index].quantity_returned" class="input"><label class="flex items-center gap-2 text-sm"><input v-model="row.restock" type="checkbox" class="mr-[10px]"> Restock</label></div></div><div class="mt-4 grid gap-3 sm:grid-cols-3"><div><label class="label">Return date</label><input v-model="returnForm.return_date" type="date" class="input"></div><div><label class="label">Refund method</label><select v-model="returnForm.refund_method" class="input"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option><option value="bank">Bank</option><option value="card">Card</option><option value="other">Other</option></select></div><div><label class="label">Estimated refund</label><div class="input bg-slate-50 font-semibold">{{ money(selectedRefund) }}</div></div><div class="sm:col-span-3"><label class="label">Reason</label><input v-model="returnForm.reason" class="input" placeholder="Reason for return"></div><div class="sm:col-span-3"><label class="label">Notes</label><input v-model="returnForm.notes" class="input" placeholder="Optional notes"></div></div><button class="btn-primary mt-4" :disabled="returnForm.processing || selectedRefund <= 0"><Icon name="refresh-circle" :size="16" /> Post return</button></form>
        </div>

        <div class="space-y-6">
            <div class="card p-5"><h2 class="font-semibold">Transaction details</h2><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between gap-4"><dt class="text-slate-500">Customer phone</dt><dd class="font-medium">{{ sale.customer_phone || '—' }}</dd></div><div class="flex justify-between gap-4"><dt class="text-slate-500">Payment reference</dt><dd class="font-medium">{{ sale.payment_reference || '—' }}</dd></div><div class="flex justify-between gap-4"><dt class="text-slate-500">Change</dt><dd class="font-medium">{{ money(sale.change_due) }}</dd></div></dl></div>
            <div class="card overflow-hidden"><div class="border-b border-slate-200 px-5 py-4"><h2 class="font-semibold">Return history</h2></div><div class="divide-y divide-slate-100"><div v-for="ret in returns" :key="ret.id" class="p-4"><div class="flex justify-between"><div><p class="font-semibold">{{ ret.reference }}</p><p class="text-xs text-slate-500">{{ ret.return_date }} · {{ ret.reason }}</p></div><b>{{ money(ret.refund_amount) }}</b></div><p class="mt-2 text-xs text-slate-500">{{ ret.refund_method }} · {{ ret.processed_by || 'Admin' }}</p></div><div v-if="!returns.length" class="p-8 text-center text-sm text-slate-400">No returns posted.</div></div></div>
            <form v-if="canVoid && sale.status !== 'voided' && Number(sale.refunded_amount || 0) === 0" class="card border-red-200 p-5" @submit.prevent="submitVoid"><h2 class="font-semibold text-red-700">Void sale</h2><p class="mt-1 text-xs text-slate-500">Voiding preserves this transaction and posts stock reversal movements. It does not delete the sale.</p><textarea v-model="voidForm.reason" class="input mt-4 min-h-24" placeholder="Required reason"></textarea><button class="mt-3 inline-flex items-center gap-2 rounded-[8px] bg-red-600 px-4 py-2.5 text-sm font-semibold text-white" :disabled="voidForm.processing" @click.prevent="submitVoid"><Icon name="close-circle" :size="16" /> Void transaction</button></form>
            <div v-if="sale.status === 'voided'" class="card border-red-200 bg-red-50 p-5"><h2 class="font-semibold text-red-700">Sale voided</h2><p class="mt-2 text-sm text-red-700">{{ sale.void_reason }}</p><p class="mt-2 text-xs text-red-600">{{ sale.voided_by_name || 'Admin' }} · {{ new Date(sale.voided_at).toLocaleString() }}</p></div>
        </div>
    </div>
</AdminLayout>
</template>
